#!/usr/bin/env python3

import csv
import json
import re
from dataclasses import dataclass
from typing import Any, Dict, List, Optional, Tuple


def load_json(path: str) -> Any:
    with open(path, "r", encoding="utf-8") as f:
        return json.load(f)


def load_csv(path: str) -> List[Dict[str, str]]:
    with open(path, "r", encoding="utf-8", newline="") as f:
        reader = csv.DictReader(f)
        return list(reader)


def norm(s: Optional[str]) -> str:
    return (s or "").strip().casefold()


_WEEK_RE = re.compile(r"^(\d{4})-W(\d{1,2})$")


def effective_week_key(s: str) -> Tuple[int, int, str]:
    """Sort key where larger means later.

    Supports YYYY-Www (ISO-ish). Falls back to lexical for unexpected formats.
    """
    ss = (s or "").strip()
    m = _WEEK_RE.match(ss)
    if m:
        return (int(m.group(1)), int(m.group(2)), ss)
    # Fallback: keep lexical order stable but comparable
    return (0, 0, ss)


def as_float(x: Any, default: float = 0.0) -> float:
    if x is None:
        return default
    if isinstance(x, (int, float)):
        return float(x)
    s = str(x).strip()
    if s == "":
        return default
    try:
        return float(s)
    except ValueError:
        return default


def as_int(x: Any, default: int = 0) -> int:
    if x is None:
        return default
    if isinstance(x, int):
        return x
    if isinstance(x, float):
        return int(x)
    s = str(x).strip()
    if s == "":
        return default
    try:
        return int(float(s))
    except ValueError:
        return default


@dataclass
class Panel:
    panel_code: str
    panel_name: str
    alias_labels: List[str]
    reagent_cost_per_1000_tests_usd: float
    network_tier: str
    shipper_class: str
    tests_per_lab_per_run_14_day: int
    tests_per_lab_per_run_28_day: int
    default_active_labs: int
    analysis_mode: str


def flatten_panels(manifest: Dict[str, Any]) -> List[Panel]:
    out: List[Panel] = []
    for cluster in manifest.get("service_clusters", []) or []:
        for p in cluster.get("panels", []) or []:
            out.append(
                Panel(
                    panel_code=str(p.get("panel_code", "")).strip(),
                    panel_name=str(p.get("panel_name", "")).strip(),
                    alias_labels=list(p.get("alias_labels", []) or []),
                    reagent_cost_per_1000_tests_usd=as_float(p.get("reagent_cost_per_1000_tests_usd"), 0.0),
                    network_tier=str(p.get("network_tier", "")).strip(),
                    shipper_class=str(p.get("shipper_class", "")).strip(),
                    tests_per_lab_per_run_14_day=as_int(p.get("tests_per_lab_per_run_14_day"), 0),
                    tests_per_lab_per_run_28_day=as_int(p.get("tests_per_lab_per_run_28_day"), 0),
                    default_active_labs=as_int(p.get("default_active_labs"), 0),
                    analysis_mode=str(p.get("analysis_mode", "")).strip(),
                )
            )
    return out


def resolve_contract_terms(
    panel: Panel, contract_rows: List[Dict[str, str]]
) -> Dict[str, Any]:
    refs = {norm(panel.panel_name)} | {norm(a) for a in (panel.alias_labels or [])}

    matches = []
    for r in contract_rows:
        if norm(r.get("status_flag")) != "current":
            continue
        if norm(r.get("panel_ref")) in refs:
            matches.append(r)

    if not matches:
        raise ValueError(f"No current contract term match for panel_code={panel.panel_code}")

    # Keep latest effective_week
    matches.sort(key=lambda rr: effective_week_key(rr.get("effective_week", "")))
    win = matches[-1]
    return {
        "panel_ref": (win.get("panel_ref") or "").strip(),
        "effective_week": (win.get("effective_week") or "").strip(),
        "base_payment_per_run_per_lab_usd": as_float(win.get("base_payment_per_run_per_lab_usd"), 0.0),
    }


def resolve_network_adjustment(panel: Panel, network_rows: List[Dict[str, str]]) -> float:
    by_tier = {norm(r.get("network_tier")): as_float(r.get("network_adjustment_per_run_per_lab_usd"), 0.0) for r in network_rows}
    return float(by_tier.get(norm(panel.network_tier), 0.0))


def resolve_active_labs(panel: Panel, override_rows: List[Dict[str, str]]) -> int:
    # Keep only approved, with non-blank rev and active_labs
    candidates = []
    for r in override_rows:
        if norm(r.get("approval")) != "approved":
            continue
        if norm(r.get("panel_code")) != norm(panel.panel_code):
            continue
        rev_s = (r.get("rev") or "").strip()
        labs_s = (r.get("active_labs") or "").strip()
        if rev_s == "" or labs_s == "":
            continue
        try:
            rev = float(rev_s)
        except ValueError:
            continue
        candidates.append((rev, r))

    if not candidates:
        return int(panel.default_active_labs)

    candidates.sort(key=lambda t: t[0])
    win = candidates[-1][1]
    return as_int(win.get("active_labs"), panel.default_active_labs)


def resolve_shipper_cost(panel: Panel, shipper_rows: List[Dict[str, str]]) -> float:
    by_class = {norm(r.get("shipper_class")): as_float(r.get("shipper_cost_usd"), 0.0) for r in shipper_rows}
    if norm(panel.shipper_class) not in by_class:
        raise ValueError(f"No shipper cost found for shipper_class={panel.shipper_class} (panel_code={panel.panel_code})")
    return float(by_class[norm(panel.shipper_class)])


# --- JSON formatting: ensure floats render with exactly 2 decimals ---
# Standard json.dumps prints floats with minimal digits (e.g., 19.1), which can
# violate an "exactly 2 decimal places" contract. This encoder formats all
# floats with 2 decimals.
import json.encoder


class TwoDecimalFloatEncoder(json.JSONEncoder):
    def iterencode(self, o, _one_shot=False):
        # Largely copied from stdlib, replacing floatstr.
        def floatstr(
            obj,
            allow_nan=self.allow_nan,
            _repr=float.__repr__,
            _inf=float("inf"),
            _neginf=-float("inf"),
        ):
            if obj != obj:
                text = "NaN"
            elif obj == _inf:
                text = "Infinity"
            elif obj == _neginf:
                text = "-Infinity"
            else:
                return format(obj, ".2f")
            if not allow_nan:
                raise ValueError(
                    "Out of range float values are not JSON compliant: " + repr(obj)
                )
            return text

        _iterencode = json.encoder._make_iterencode(
            markers={},
            _default=self.default,
            _encoder=json.encoder.encode_basestring,
            _indent=self.indent,
            _floatstr=floatstr,
            _key_separator=self.key_separator,
            _item_separator=self.item_separator,
            _sort_keys=self.sort_keys,
            _skipkeys=self.skipkeys,
            _one_shot=_one_shot,
        )
        return _iterencode(o, 0)


def main() -> None:
    panel_manifest = load_json("/root/panel_manifest.json")
    holdouts = load_json("/root/holdouts.json")
    report_template = load_json("/root/report_template.json")

    shipper_cost_rows = load_csv("/root/shipper_cost.csv")
    contract_rows = load_csv("/root/contract_terms.csv")
    network_rows = load_csv("/root/network_adjustments.csv")
    override_rows = load_csv("/root/lab_capacity_overrides.csv")

    panels = flatten_panels(panel_manifest)

    # Filter: analysis_mode == "review"
    review_panels = [p for p in panels if norm(p.analysis_mode) == "review"]

    # Exclude holdouts where holdout_state == "exclude"
    excluded_codes = {
        norm(h.get("panel_code"))
        for h in (holdouts.get("holdouts", []) or [])
        if norm(h.get("holdout_state")) == "exclude"
    }
    retained = [p for p in review_panels if norm(p.panel_code) not in excluded_codes]

    # Determine shipper cost basis (per-shipment vs annual) from magnitude.
    # In this dataset, costs are small (tens of USD) and vary only by class,
    # which strongly suggests per-shipment costs.
    shipper_cost_values = [as_float(r.get("shipper_cost_usd"), 0.0) for r in shipper_cost_rows]
    max_shipper_cost = max(shipper_cost_values) if shipper_cost_values else 0.0
    shipper_cost_is_per_shipment = max_shipper_cost < 200.0
    shipper_cost_basis = "per_shipment" if shipper_cost_is_per_shipment else "annual"

    RUNS_PER_YEAR_14 = 26
    RUNS_PER_YEAR_28 = 13
    SWITCH_THRESHOLD_USD = 6000

    panel_outputs: List[Dict[str, Any]] = []

    total_margin_14 = 0.0
    total_margin_28 = 0.0

    for p in retained:
        contract = resolve_contract_terms(p, contract_rows)
        base_payment = float(contract["base_payment_per_run_per_lab_usd"])

        net_adj = resolve_network_adjustment(p, network_rows)
        total_payment = base_payment + net_adj

        active_labs = resolve_active_labs(p, override_rows)
        shipper_cost_usd = resolve_shipper_cost(p, shipper_cost_rows)

        def compute_for_cadence(runs_per_year: int, tests_per_lab_per_run: int) -> Dict[str, float]:
            annual_revenue = total_payment * active_labs * runs_per_year
            annual_reagent_cost = (
                p.reagent_cost_per_1000_tests_usd
                * active_labs
                * tests_per_lab_per_run
                * runs_per_year
                / 1000.0
            )
            if shipper_cost_is_per_shipment:
                annual_shipper_cost = shipper_cost_usd * runs_per_year
            else:
                annual_shipper_cost = shipper_cost_usd
            annual_margin = annual_revenue - annual_reagent_cost - annual_shipper_cost
            return {
                "annual_revenue_usd": annual_revenue,
                "annual_reagent_cost_usd": annual_reagent_cost,
                "annual_shipper_cost_usd": annual_shipper_cost,
                "annual_margin_usd": annual_margin,
            }

        fin14 = compute_for_cadence(RUNS_PER_YEAR_14, p.tests_per_lab_per_run_14_day)
        fin28 = compute_for_cadence(RUNS_PER_YEAR_28, p.tests_per_lab_per_run_28_day)

        margin_diff_28_minus_14 = fin28["annual_margin_usd"] - fin14["annual_margin_usd"]

        total_margin_14 += fin14["annual_margin_usd"]
        total_margin_28 += fin28["annual_margin_usd"]

        panel_outputs.append(
            {
                "panel_code": p.panel_code,
                "panel_name": p.panel_name,
                "alias_labels": list(p.alias_labels),
                "network_tier": p.network_tier,
                "shipper_class": p.shipper_class,
                "contract": {
                    "matched_panel_ref": contract["panel_ref"],
                    "effective_week": contract["effective_week"],
                    "base_payment_per_run_per_lab_usd": round(base_payment, 2),
                },
                "network_adjustment_per_run_per_lab_usd": round(net_adj, 2),
                "total_payment_per_run_per_lab_usd": round(total_payment, 2),
                "active_labs": int(active_labs),
                "tests_per_lab_per_run_14_day": int(p.tests_per_lab_per_run_14_day),
                "tests_per_lab_per_run_28_day": int(p.tests_per_lab_per_run_28_day),
                "reagent_cost_per_1000_tests_usd": round(p.reagent_cost_per_1000_tests_usd, 2),
                "shipper_cost_usd": round(shipper_cost_usd, 2),
                "shipper_cost_basis": shipper_cost_basis,
                "cadence_financials": {
                    "14_day": {
                        "runs_per_year": RUNS_PER_YEAR_14,
                        **{k: round(v, 2) for k, v in fin14.items()},
                    },
                    "28_day": {
                        "runs_per_year": RUNS_PER_YEAR_28,
                        **{k: round(v, 2) for k, v in fin28.items()},
                    },
                },
                "annual_margin_difference_28_minus_14_usd": round(margin_diff_28_minus_14, 2),
            }
        )

    panel_outputs.sort(key=lambda x: x["panel_code"])

    total_diff = total_margin_28 - total_margin_14
    abs_total_diff = abs(total_diff)

    if abs_total_diff < SWITCH_THRESHOLD_USD:
        decision = "adopt_28_day"
    else:
        decision = "keep_14_day"

    output = {
        "metadata": report_template.get("metadata"),
        "audit_notes": report_template.get("audit_notes"),
        "analysis": {
            "assumptions": {
                "runs_per_year_14_day": RUNS_PER_YEAR_14,
                "runs_per_year_28_day": RUNS_PER_YEAR_28,
                "switch_threshold_usd": SWITCH_THRESHOLD_USD,
                "shipper_cost_basis": shipper_cost_basis,
                "contract_status_flag_required": "current",
                "contract_match_fields": ["panel_name", "alias_labels"],
                "network_missing_tier_adjustment_usd": 0.0,
                "lab_override_approval_required": "approved",
                "lab_override_rev_selection": "max",
                "currency": "USD",
            },
            "panels": panel_outputs,
            "totals": {
                "total_annual_margin_14_day_usd": round(total_margin_14, 2),
                "total_annual_margin_28_day_usd": round(total_margin_28, 2),
                "total_annual_margin_difference_28_minus_14_usd": round(total_diff, 2),
                "absolute_total_margin_difference_usd": round(abs_total_diff, 2),
                "retained_panel_count": int(len(panel_outputs)),
            },
            "recommendation": {
                "decision": decision,
                "absolute_total_margin_difference_usd": round(abs_total_diff, 2),
                "switch_threshold_usd": SWITCH_THRESHOLD_USD,
            },
        },
    }

    with open("/root/diagpanel_policy_report.json", "w", encoding="utf-8") as f:
        json.dump(output, f, indent=2, cls=TwoDecimalFloatEncoder, ensure_ascii=False)
        f.write("\n")

    # Markdown summary: 4-8 non-empty lines
    summary_lines = [
        "Diagnostic panel replenishment cadence analysis (14-day vs 28-day)",
        f"Total annual margin (14-day): ${total_margin_14:,.2f}",
        f"Total annual margin (28-day): ${total_margin_28:,.2f}",
        f"Absolute total margin difference: ${abs_total_diff:,.2f}",
        f"Decision: {decision}",
    ]

    with open("/root/diagpanel_policy_summary.md", "w", encoding="utf-8") as f:
        f.write("\n".join(summary_lines) + "\n")


if __name__ == "__main__":
    main()

