                "tests_per_lab_per_run_14_day": int(p.tests_per_lab_per_run_14_day),
                "tests_per_lab_per_run_28_day": int(p.tests_per_lab_per_run_28_day),
                "reagent_cost_per_1000_tests_usd": round(p.reagent_cost_per_1000_tests_usd, 2),
                "shipper_cost_usd": round(shipper_cost_usd, 2),
